    "source": "flowchart TB\r\n  UI[\"1 · GET /empresas/:id<br/>seleccionar o cargar\"] --> LOOKUP[\"Backend: resolver RUT\"]\r\n  LOOKUP -->|\"LEE si hay ID local\"| ID[(\"empresas + personas\")]\r\n  LOOKUP -->|\"GET cliente, _rutCliente\"| REMOTE[\"API clientes configurada<br/>receptor por verificar\"]\r\n  REMOTE -->|\"2 · Respuesta válida\"| SAVE[\"Guardar ficha con trx\"]\r\n  subgraph PG[\"PostgreSQL sucursal · actualización local\"]\r\n    CLIENT[(\"personas + empresas\")]\r\n    ADDRESS[(\"direccion_empresas<br/>direcciones\")]\r\n    ACCOUNT[(\"estado_cuentas<br/>cupo y plazo\")]\r\n  end\r\n  SAVE -->|\"LEE / ESCRIBE\"| CLIENT\r\n  SAVE -->|\"LEE / ESCRIBE según payload\"| ADDRESS\r\n  SAVE -->|\"LEE plazo / ESCRIBE cuenta\"| ACCOUNT\r\n  SAVE -->|\"3 · Tras guardados\"| COMMIT[\"COMMIT ficha<br/>releer relaciones locales\"]\r\n  COMMIT -->|\"Rama id=null: ID, o sin saldo\"| OUT[\"Respuesta a la interfaz\"]\r\n  COMMIT -->|\"4 · Solo cuando corresponde\"| SALDO[\"GET saldo y recálculo<br/>fuera de la trx de ficha\"]\r\n  SALDO -->|\"ESCRIBE saldo externo y derivados\"| ACCOUNT\r\n  SALDO --> OUT\n",
